from __future__ import annotations

from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import PRODUCT_FULL_NAME
from .plans import GAME_CREATE

router = APIRouter(tags=["Aura Game Gameplay Portal"])


@router.get("/game-creation/gameplay/{game_id}", response_class=HTMLResponse, include_in_schema=False)
def gameplay_portal(game_id: str, request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        return RedirectResponse(f"/signin?next=/game-creation/gameplay/{escape(game_id, quote=True)}", status_code=303)
    if not member.plan.has(GAME_CREATE):
        return RedirectResponse("/game-creation", status_code=303)
    safe_game_id = escape(game_id, quote=True)
    safe_brand = escape(PRODUCT_FULL_NAME)
    return HTMLResponse(
        """<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='robots' content='noindex,nofollow'><title>Gameplay & Physics — __BRAND__</title><style>
:root{--bg:#03050b;--panel:#0d1220;--line:#ffffff20;--gold:#efca6d;--violet:#986cff;--cyan:#5be1ff;--green:#79dda5;--red:#ff8fa5;--muted:#bac3d4}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 7% 0,#42156866,transparent 33%),radial-gradient(circle at 95% 8%,#12415f66,transparent 30%),var(--bg);color:#fff;font-family:Inter,system-ui,sans-serif}.wrap{width:min(1420px,calc(100% - 24px));margin:auto}.nav{position:sticky;top:0;z-index:20;border-bottom:1px solid var(--line);background:#05070eee;backdrop-filter:blur(15px)}.navin{min-height:66px;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.brand{color:#fff;text-decoration:none;font-weight:950}.brand small{display:block;color:var(--gold);font-size:.66rem;text-transform:uppercase;letter-spacing:.12em}.hero{padding:34px 0 18px}.eyebrow{color:var(--gold);font-size:.68rem;text-transform:uppercase;letter-spacing:.14em;font-weight:950}h1{font-size:clamp(2.3rem,6vw,5rem);line-height:.92;letter-spacing:-.05em;margin:.14em 0}.muted{color:var(--muted);line-height:1.55}.grid{display:grid;grid-template-columns:.82fr 1.18fr;gap:12px;padding-bottom:70px}.card{border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,#111729e8,#090d18ed);padding:15px;margin-bottom:11px}.row{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.form{display:grid;gap:8px}.two{display:grid;grid-template-columns:1fr 1fr;gap:8px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}input,select,button{font:inherit}input,select{width:100%;border:1px solid var(--line);background:#070a12;color:#fff;border-radius:10px;padding:9px}button,.btn{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:10px;padding:9px 11px;font-weight:850;cursor:pointer;text-decoration:none}.primary{border:0;background:linear-gradient(120deg,var(--gold),var(--violet));color:#160c1d}.good{border-color:#79dda566;color:var(--green)}.danger{border-color:#ff8fa566;color:#ffd7df}.entity{border:1px solid var(--line);border-radius:14px;background:#ffffff05;padding:12px;margin:9px 0}.entity h3{margin:4px 0}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:.7rem;margin:2px}.mini{font-size:.75rem;color:var(--muted)}.notice{display:none;margin-top:10px;padding:10px;border:1px solid var(--line);border-radius:10px}.notice.show{display:block}.empty{padding:22px;border:1px dashed #ffffff2d;border-radius:12px;text-align:center;color:var(--muted)}.physics{border-left:3px solid var(--cyan);padding-left:10px}.runtime{border-left:3px solid var(--green);padding-left:10px}.entityEdit{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;margin-top:9px}.entityActions{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.core{opacity:.78}.codeSafety{font-size:.78rem;padding:9px;border:1px solid #79dda544;background:#79dda50c;border-radius:10px}@media(max-width:980px){.grid{grid-template-columns:1fr}.entityEdit{grid-template-columns:repeat(3,1fr)}}@media(max-width:580px){.two,.three,.entityEdit{grid-template-columns:1fr}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/game-creation'>__BRAND__<small>Aura Game Forge · Gameplay & Physics</small></a><div><a class='btn' href='/game-creation'>← Game Forge</a> <button id='scanBtn'>Scan</button> <button id='buildBtn' class='primary'>Build & Play</button></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>No-code World DNA gameplay</div><h1 id='title'>Gameplay & Physics</h1><p class='muted'>Create collectibles, hazards, checkpoints, triggers, moving platforms and patrolling NPCs as declarative Aura World DNA. The runtime executes only allow-listed behavior parameters—never creator JavaScript, Python, fetched scripts or generated server code.</p><div id='notice' class='notice'></div></section><section class='grid'><div><div class='card'><div class='eyebrow'>Add gameplay entity</div><h2>Place a safe preset</h2><form id='createForm' class='form'><div class='two'><input id='newName' maxlength='160' placeholder='Entity name' required><select id='newPreset'><option value='collectible'>Collectible</option><option value='hazard'>Hazard</option><option value='checkpoint'>Checkpoint</option><option value='moving_platform'>Moving platform</option><option value='trigger'>Quest/event trigger</option><option value='npc_patrol'>Patrolling NPC</option></select></div><div class='three'><input id='newX' type='number' step='0.1' value='0' aria-label='X position'><input id='newY' type='number' step='0.1' value='0' aria-label='Y position'><input id='newZ' type='number' step='0.1' value='0' aria-label='Z position'></div><div class='three'><input id='newSX' type='number' step='0.1' value='1' aria-label='X scale'><input id='newSY' type='number' step='0.1' value='1' aria-label='Y scale'><input id='newSZ' type='number' step='0.1' value='1' aria-label='Z scale'></div><button class='primary' type='submit'>Add to World DNA</button></form></div><div class='card physics'><div class='eyebrow'>Physics model</div><h3>Aura Physics DNA</h3><p class='muted'>Presets select bounded collision shapes, layers and static/kinematic/trigger modes automatically. Dynamic non-player bodies use the world's gravity and bounded restitution in playtests. Trigger collisions drive collectibles, damage, checkpoints and events.</p></div><div class='card runtime'><div class='eyebrow'>Runtime contract</div><div id='runtimeInfo' class='muted'>Loading gameplay runtime…</div></div><div class='codeSafety'>🔐 Runtime network access remains disabled. Gameplay DNA changes invalidate stale builds and rating scans. Publishing stays bound to the complete Game DNA + World DNA + media/model/cinematic/gameplay integrity hash.</div></div><div><div class='card'><div class='row'><div><div class='eyebrow'>World entities</div><h2>Gameplay scene graph</h2></div><button id='refreshBtn'>Refresh</button></div><div id='entities'><div class='empty'>Loading World DNA…</div></div></div></div></section></main><script>
'use strict';const GAME_ID='__GAME_ID__';const $=id=>document.getElementById(id);const PRESETS=['collectible','hazard','checkpoint','moving_platform','trigger','npc_patrol'];function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function n(v,d=0){const x=Number(v);return Number.isFinite(x)?x:d}function notice(v,bad=false){const el=$('notice');el.textContent=v;el.className='notice show';el.style.borderColor=bad?'#ff8fa566':'#79dda566';clearTimeout(window.__nt);window.__nt=setTimeout(()=>el.className='notice',6500)}async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch{}if(!r.ok)throw new Error(typeof b.detail==='string'?b.detail:(b.detail?.message||`Request failed (${r.status})`));return b}
function behaviorLabel(e){return (e.behaviors||[]).filter(b=>b.enabled!==false).map(b=>b.op).join(', ')||'none'}function physicsLabel(e){if(!e.physics)return'No collision body';return`${e.physics.mode} · ${e.physics.shape} · layer ${e.physics.collision_layer}`}
function entityCard(e){const t=e.transform||{},p=t.position||{},s=t.scale||{},core=e.id==='player'||e.id==='camera';const options=PRESETS.map(x=>`<option value='${x}'>${esc(x.replaceAll('_',' '))}</option>`).join('');return`<article class='entity ${core?'core':''}' data-entity-id='${esc(e.id)}'><div class='row'><div><span class='pill'>${esc(e.kind)}</span>${core?'<span class="pill good">protected core</span>':''}<h3>${esc(e.name)}</h3><div class='mini'>${esc(physicsLabel(e))}<br>Behaviors: ${esc(behaviorLabel(e))}</div></div><div class='mini'>${esc(e.id)}</div></div><div class='entityEdit'><input data-field='name' value='${esc(e.name)}' aria-label='Name'><input data-field='x' type='number' step='.1' value='${n(p.x)}' aria-label='X'><input data-field='y' type='number' step='.1' value='${n(p.y)}' aria-label='Y'><input data-field='z' type='number' step='.1' value='${n(p.z)}' aria-label='Z'><input data-field='sx' type='number' step='.1' value='${n(s.x,1)}' aria-label='Scale X'><input data-field='sy' type='number' step='.1' value='${n(s.y,1)}' aria-label='Scale Y'><input data-field='sz' type='number' step='.1' value='${n(s.z,1)}' aria-label='Scale Z'></div><div class='entityActions'><button data-action='save'>Save transform</button>${core?'':`<select data-field='preset'>${options}</select><button data-action='preset'>Apply preset</button><button data-action='delete' class='danger'>Delete</button>`}</div></article>`}
async function load(){try{const [game,state]=await Promise.all([api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}`),api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/gameplay`)]);$('title').textContent=`${game.title} · Gameplay & Physics`;$('entities').innerHTML=(state.entities||[]).map(entityCard).join('')||'<div class="empty">No World DNA entities.</div>';const r=state.runtime||{};$('runtimeInfo').innerHTML=`World revision <b>${esc(state.world_revision)}</b><br>${esc((r.supported_behaviors||[]).join(' · '))}<br>Arbitrary script source: <b>${r.arbitrary_script_source_allowed?'enabled':'disabled'}</b>`}catch(e){$('entities').innerHTML=`<div class='empty'>${esc(e.message)}</div>`;notice(e.message,true)}}
$('createForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/gameplay/entities`,{method:'POST',body:JSON.stringify({name:$('newName').value,preset:$('newPreset').value,position:{x:n($('newX').value),y:n($('newY').value),z:n($('newZ').value)},scale:{x:n($('newSX').value,1),y:n($('newSY').value,1),z:n($('newSZ').value,1)}})});notice('Gameplay entity added. Previous build/rating invalidated.');$('newName').value='';await load()}catch(err){notice(err.message,true)}});
$('entities').addEventListener('click',async e=>{const button=e.target.closest('button[data-action]');if(!button)return;const card=button.closest('[data-entity-id]'),id=card?.dataset.entityId;if(!id)return;const get=f=>card.querySelector(`[data-field="${f}"]`);try{if(button.dataset.action==='save'){await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/gameplay/entities/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({name:get('name').value,position:{x:n(get('x').value),y:n(get('y').value),z:n(get('z').value)},scale:{x:n(get('sx').value,1),y:n(get('sy').value,1),z:n(get('sz').value,1)}})});notice('World DNA entity updated.')}else if(button.dataset.action==='preset'){await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/gameplay/entities/${encodeURIComponent(id)}/preset`,{method:'POST',body:JSON.stringify({preset:get('preset').value})});notice('Gameplay preset applied.')}else if(button.dataset.action==='delete'){if(!confirm('Delete this gameplay entity from World DNA?'))return;await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/gameplay/entities/${encodeURIComponent(id)}`,{method:'DELETE'});notice('Gameplay entity deleted.')}await load()}catch(err){notice(err.message,true)}});
$('refreshBtn').addEventListener('click',load);$('scanBtn').addEventListener('click',async()=>{try{const r=await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/scan`,{method:'POST'});notice(r.public_test_allowed?'Integrity/rating scan passed.':`Scan completed with ${(r.blockers||[]).length} blocker(s).`,!r.public_test_allowed)}catch(e){notice(e.message,true)}});$('buildBtn').addEventListener('click',async()=>{try{const r=await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/build`,{method:'POST'});notice(`Built ${r.runtime}. Opening private playtest…`);window.open(r.private_playtest_url,'_blank','noopener')}catch(e){notice(e.message,true)}});load();
</script></body></html>"""
        .replace("__BRAND__", safe_brand)
        .replace("__GAME_ID__", safe_game_id)
    )


__all__ = ["router"]
